import React, { useState } from 'react';
import MenuCategories from './Menu/MenuCategories';
import MenuItems from './Menu/MenuItems';
import MenuItemsList from './Menu/MenuItemsList';
import MenuItemsWithOptions from './Menu/MenuItemsWithOptions';
import CartItemWithOptions from './Cart/CartItemWithOptions';
import POSTerminal from './POSTerminal';
import './StyleGuide.css';

const StyleGuide = () => {
  const [selectedCategory, setSelectedCategory] = useState(1);
  const [cartItems, setCartItems] = useState([
    {
      id: 1,
      name: 'Bulgogi Rice Bowl',
      price: 18.50,
      quantity: 2,
      options: { size: 'L', spice: 'hot', toppings: ['cheese'] }
    },
    {
      id: 2,
      name: 'Kimchi Fried Rice',
      price: 15.90,
      quantity: 1,
      options: { size: 'M', spice: 'mild', toppings: [] }
    }
  ]);

  // 테스트용 더미 데이터
  const mockCategories = [
    { id: 1, name: 'Korean Food' },
    { id: 2, name: 'Japanese' },
    { id: 3, name: 'Western' },
    { id: 4, name: 'Beverages' },
    { id: 5, name: 'Desserts' }
  ];

  const mockMenuItems = [
    { id: 1, name: 'Bulgogi Rice Bowl', description: 'Marinated beef with steamed rice and vegetables', price: 18.50 },
    { id: 2, name: 'Kimchi Fried Rice', description: 'Spicy fermented cabbage fried rice with egg', price: 15.90 },
    { id: 3, name: 'Korean BBQ Set', description: 'Grilled pork belly with banchan and rice', price: 25.90 }
  ];

  const handleCartUpdate = (itemId, updates) => {
    setCartItems(prev => prev.map(item => 
      item.id === itemId ? { ...item, ...updates } : item
    ));
  };

  const handleCartRemove = (itemId) => {
    setCartItems(prev => prev.filter(item => item.id !== itemId));
  };

  return (
    <div className="style-guide">
      <h1>POS System Style Guide</h1>

      <section className="guide-section">
        <h2>Menu Categories</h2>
        <MenuCategories 
          categories={mockCategories}
          onCategorySelect={setSelectedCategory}
          selectedCategory={selectedCategory}
        />
      </section>

      <section className="guide-section">
        <h2>Menu Items - Card Style</h2>
        <MenuItems 
          items={mockMenuItems}
          onItemSelect={(item) => console.log('Selected:', item)}
        />
      </section>

      <section className="guide-section">
        <h2>Menu Items - List Style</h2>
        <MenuItemsList 
          items={mockMenuItems}
          onItemSelect={(item) => console.log('Selected:', item)}
        />
      </section>

      <section className="guide-section">
        <h2>B방식: Menu Items with Options (메뉴에서 바로 옵션 선택)</h2>
        <MenuItemsWithOptions 
          items={mockMenuItems.slice(0, 2)}
          onItemSelect={(item) => console.log('Added with options:', item)}
        />
      </section>

      <section className="guide-section">
        <h2>C방식: Cart Items with Options (장바구니에서 옵션 수정)</h2>
        <div style={{ maxWidth: '400px', padding: '16px', background: 'white', border: '1px solid #E6EBF1', borderRadius: '8px' }}>
          {cartItems.map(item => (
            <CartItemWithOptions
              key={item.id}
              item={item}
              onUpdate={handleCartUpdate}
              onRemove={handleCartRemove}
            />
          ))}
        </div>
      </section>

      <section className="guide-section pos-terminal-section">
        <h2>Complete POS Terminal</h2>
        <div className="pos-terminal-preview">
          <POSTerminal />
        </div>
      </section>

      <section className="guide-section">
        <h2>Color Palette</h2>
        <div className="color-palette">
          <div className="color-box primary">#6A7FFF</div>
          <div className="color-box secondary">#84CEE0</div>
          <div className="color-box success">#96DF8B</div>
          <div className="color-box warning">#FF9B5D</div>
          <div className="color-box danger">#E9626C</div>
        </div>
      </section>

      <section className="guide-section">
        <h2>Buttons</h2>
        <div className="button-showcase">
          <button className="btn btn-primary">Primary</button>
          <button className="btn btn-secondary">Secondary</button>
          <button className="btn btn-success">Success</button>
          <button className="btn btn-warning">Warning</button>
          <button className="btn btn-danger">Danger</button>
        </div>
      </section>
    </div>
  );
};

export default StyleGuide;
